3	commerce	{\n        "hero": {\n            "title": "Commerce & Management Career Guide",\n            "subtitle": "Courses, Entrance Exams, Colleges & Career Scope — A Complete Roadmap",\n            "description": "Commerce opens one of the widest sets of career doors — B.Com, BBA, MBA, CA, CS, CMA, banking, finance, taxation, and management. But the sheer number of options can make it hard to know where to start or what path makes the most sense for you. This page brings it all together clearly.",\n            "description2": "Whether you've just completed Class 12 (Commerce) and are choosing your first degree, or you're a graduate planning your next move — MBA, professional certification, or a career switch — you'll find clear pathways, course options, exam guidance, and direct links to detailed pages across the portal.",\n            "heroStats": [\n                {\n                    "icon": "ClipboardList",\n                    "label": "Popular paths after 12",\n                    "value": "B.Com · BBA · CA Foundation"\n                },\n                {\n                    "icon": "BadgeCheck",\n                    "label": "Need guidance?",\n                    "value": "Counselor Support"\n                }\n            ],\n            "quickLinks": [\n                {\n                    "desc": "Step-by-step pathway after 12 for commerce students.",\n                    "href": "/careers/after-class-12-commerce",\n                    "icon": "GraduationCap",\n                    "title": "After Class 12 • Commerce"\n                },\n                {\n                    "desc": "B.Com, B.Com (Hons) and allied graduation courses.",\n                    "href": "/courses/bcom-allied-programs",\n                    "icon": "BookOpen",\n                    "title": "B.Com Programs"\n                },\n                {\n                    "desc": "Management degrees from UG to PG level.",\n                    "href": "/courses/bba",\n                    "icon": "Briefcase",\n                    "title": "BBA / MBA"\n                },\n                {\n                    "desc": "Professional commerce certifications and exam paths.",\n                    "href": "/courses/professional",\n                    "icon": "Award",\n                    "title": "CA / CS / CMA"\n                }\n            ]\n        },\n        "primaryExam": {\n            "heading": "CAT: The Main MBA Entrance Exam",\n            "intro": "CAT (Common Admission Test) is India's most competitive management entrance examination, conducted by the IIMs on a rotational basis. A strong CAT score is the primary route to MBA / PGDM programmes at IIMs and hundreds of top business schools across the country. If your long-term goal is a management career at a senior level, CAT is the exam that defines your trajectory.",\n            "quickFacts": [\n                {\n                    "label": "Sections",\n                    "value": "VARC • DILR • Quantitative Aptitude"\n                },\n                {\n                    "label": "Question Type",\n                    "value": "MCQ + TITA (CBT)"\n                },\n                {\n                    "label": "Used For",\n                    "value": "MBA / PGDM Admissions"\n                }\n            ],\n            "purpose": "Admission to MBA / PGDM programmes at the IIMs (primary purpose). CAT scores are also accepted by hundreds of other top business schools — including FMS Delhi, SPJIMR, MDI, IMT, and many more — as their primary or supplementary criterion.",\n            "eligibility": [\n                {\n                    "category": "General Category",\n                    "details": "Bachelor's degree with minimum 50% aggregate (or equivalent CGPA) in any discipline"\n                },\n                {\n                    "category": "SC / ST / PWD",\n                    "details": "Bachelor's degree with minimum 45% aggregate (or equivalent CGPA)"\n                },\n                {\n                    "category": "Final Year Students",\n                    "details": "Students in the final year of their graduation can apply provisionally"\n                }\n            ],\n            "applyMode": "Online Application Mode (iimcat.ac.in)",\n            "officialWebsite": "https://iimcat.ac.in/",\n            "unlocks": [\n                "IIMs — Ahmedabad, Bangalore, Calcutta, and 17+ others across India",\n                "FMS Delhi, SPJIMR, MDI Gurgaon, IMT Ghaziabad and many other top non-IIM schools",\n                "Hundreds of AICTE-approved MBA/PGDM institutes that accept CAT scores",\n                "Specialisations: Finance, Marketing, HR, Operations, Strategy, Analytics, Consulting and more"\n            ],\n            "otherExams": [\n                {\n                    "name": "XAT",\n                    "description": "Conducted by XLRI Jamshedpur. Accepted by XLRI, XIMB and 150+ institutes. Has a Decision Making section unique to management testing."\n                },\n                {\n                    "name": "MAT / CMAT",\n                    "description": "MAT is conducted by AIMA; CMAT by NTA. Both are accepted by a large number of AICTE-approved management institutes and are less competitive than CAT."\n                }\n            ],\n            "whoShouldFocusIntro": "CAT preparation is best suited for students who are comfortable with reading comprehension, logical reasoning, and basic quantitative maths. It rewards accuracy and calm test temperament — not speed alone.",\n            "whoShouldFocusPoints": [\n                "You are targeting a senior management or consulting career path",\n                "You have a graduation degree (or are in the final year) in any stream",\n                "You are willing to prepare consistently for 6–12 months with daily practice",\n                "You can handle timed problem-solving under pressure without losing accuracy"\n            ],\n            "prepPlan": [\n                {\n                    "title": "Diagnose your baseline — take a free mock first",\n                    "description": "Before starting any preparation, attempt one free mock CAT to understand where you stand in all three sections. This helps you allocate study time correctly from the start — most students waste months on sections they are already decent at."\n                },\n                {\n                    "title": "Build VARC and DILR through daily reading and puzzles",\n                    "description": "Verbal Ability and Reading Comprehension improves with consistent reading of quality articles (newspapers, editorials, business writing). DILR requires daily puzzle-solving and logic practice. These two sections cannot be crammed — they need steady, long-term exposure."\n                },\n                {\n                    "title": "Quantitative Aptitude — clear concepts, then practise patterns",\n                    "description": "QA covers arithmetic, algebra, geometry, and number systems from Class 10–12 level. Clear each concept area before moving on. Once concepts are solid, QA improvement is the fastest with consistent problem-solving practice."\n                },\n                {\n                    "title": "Weekly mocks + deep analysis — this is where the score improves",\n                    "description": "From 3 months before the exam, take full-length mocks weekly and spend twice the test time on analysis. Track which question types lose you the most marks and fix those specifically. In CAT, strategy (what to attempt and what to skip) matters as much as knowledge."\n                }\n            ]\n        },\n        "professionalCertifications": {\n            "title": "Professional Commerce: CA / CS / CMA",\n            "subtitle": "Alongside degree programmes, these professional certifications are among the most respected commerce career routes.",\n            "description": "CA (Chartered Accountant), CS (Company Secretary), and CMA (Cost and Management Accountant) are professional qualifications that can be pursued alongside or after a B.Com degree. They are highly valued by employers and open doors to corporate finance, audit, taxation, legal compliance, and advisory roles.",\n            "cards": [\n                {\n                    "icon": "CircleDollarSign",\n                    "title": "CA — Chartered Accountant",\n                    "description": "Conducted by ICAI. Three stages: Foundation → Intermediate → Final. One of India's most respected and demanding professional qualifications. Leads to careers in audit, taxation, corporate finance, and advisory."\n                },\n                {\n                    "icon": "Scale",\n                    "title": "CS — Company Secretary",\n                    "description": "Conducted by ICSI. Three stages: Foundation → Executive → Professional. Focuses on corporate law, governance, and compliance. CS professionals are mandatory in listed companies above a certain size."\n                },\n                {\n                    "icon": "BarChart2",\n                    "title": "CMA — Cost & Management Accountant",\n                    "description": "Conducted by ICAI (CMA). Three stages: Foundation → Intermediate → Final. Focuses on cost accounting, management accounting, and financial management. Strong demand in manufacturing, PSUs, and large corporations."\n                }\n            ]\n        },\n        "pathways": {\n            "title": "Choose Your Commerce Pathway",\n            "subtitle": "Pick your stage, then follow the most realistic path based on your goals and eligibility.",\n            "after12": {\n                "title": "After Class 12th (Commerce)",\n                "description": "Class 12 Commerce students have several strong immediate options. The most common are B.Com (for a broad academic base), BBA (for early management exposure), and CA Foundation (for the professional CA route). You do not have to choose only one — B.Com and CA Foundation can be pursued together.",\n                "points": [\n                    "Best for: Students targeting finance, accounts, management, or business careers",\n                    "Good options: B.Com / B.Com (Hons), BBA, CA Foundation, CS Foundation, CMA Foundation",\n                    "Smart strategy: Start CA Foundation alongside B.Com for maximum career optionality"\n                ],\n                "links": [\n                    {\n                        "label": "After Class 12 • Commerce",\n                        "meta": "Stage",\n                        "href": "/careers/after-class-12-commerce"\n                    },\n                    {\n                        "label": "B.Com & Allied Programs",\n                        "meta": "UG",\n                        "href": "/courses/bcom-allied-programs"\n                    },\n                    {\n                        "label": "BBA & UG Management",\n                        "meta": "UG",\n                        "href": "/courses/bba"\n                    },\n                    {\n                        "label": "CA / CS / CMA",\n                        "meta": "Professional",\n                        "href": "/courses/professional"\n                    }\n                ]\n            },\n            "afterGraduation": {\n                "title": "After Graduation",\n                "description": "Graduates from any stream can pursue an MBA. Commerce and BBA graduates specifically have strong options in M.Com (for academic depth) and MBA (for management careers). The key decision is whether you want a purely academic PG path or a professional/industry-oriented one.",\n                "points": [\n                    "MBA route: Requires CAT / XAT / MAT score + group discussion + interview",\n                    "M.Com route: University entrance or merit-based admission; best for academic and teaching careers",\n                    "CA / CS / CMA completion: Can be done alongside graduation for an integrated qualification"\n                ],\n                "links": [\n                    {\n                        "label": "MBA / PGDM",\n                        "meta": "PG",\n                        "href": "/courses/business-management/mba"\n                    },\n                    {\n                        "label": "M.Com & PG Commerce",\n                        "meta": "PG",\n                        "href": "/courses/mcom"\n                    },\n                    {\n                        "label": "MBA & Management Exams",\n                        "meta": "Exams",\n                        "href": "/exams/law/management"\n                    },\n                    {\n                        "label": "After Graduation Guidance",\n                        "meta": "Stage",\n                        "href": "/careers/after-graduation"\n                    }\n                ]\n            }\n        },\n        "courseBranches": {\n            "intro": "Commerce careers are not limited to accounts or banking. The domain spans business management, financial services, corporate law, cost analysis, data analytics for business, and entrepreneurship. Choose based on what genuinely excites you — the depth of finance, the breadth of management, or the rigour of professional qualifications.",\n            "cards": [\n                {\n                    "icon": "BookOpen",\n                    "title": "B.Com & M.Com (Academic Route)",\n                    "description": "The foundational commerce degree. B.Com builds broad knowledge in accounts, economics, taxation, and business law. M.Com deepens this for teaching, research, or senior roles.",\n                    "points": [\n                        "Best for: Students who want a broad academic base with flexible career options",\n                        "Commonly paired with: CA / CS / CMA preparation simultaneously",\n                        "Outcome: Accountant, auditor, finance executive, tax professional, or higher studies"\n                    ],\n                    "links": [\n                        {\n                            "label": "B.Com & Allied Programs",\n                            "href": "/courses/bcom-allied-programs"\n                        },\n                        {\n                            "label": "M.Com & PG Commerce",\n                            "meta": "PG",\n                            "href": "/courses/mcom"\n                        }\n                    ]\n                },\n                {\n                    "icon": "Briefcase",\n                    "title": "BBA & MBA (Management Route)",\n                    "description": "BBA is a 3-year management degree after Class 12. MBA/PGDM is the top postgraduate management qualification, ideally pursued after 2+ years of work experience for maximum value.",\n                    "points": [\n                        "Best for: Students targeting business leadership, consulting, marketing, or general management",\n                        "Main gate (MBA): CAT · XAT · MAT · CMAT",\n                        "Outcome: Manager, consultant, analyst, entrepreneur, or specialist in HR/Finance/Marketing"\n                    ],\n                    "links": [\n                        {\n                            "label": "BBA & UG Management",\n                            "href": "/courses/bba"\n                        },\n                        {\n                            "label": "MBA / PGDM",\n                            "meta": "PG",\n                            "href": "/courses/mba-pgdm"\n                        }\n                    ]\n                },\n                {\n                    "icon": "Award",\n                    "title": "CA / CS / CMA (Professional Route)",\n                    "description": "These are self-paced professional qualifications with high earning potential. They are demanding but respected globally and can be started right after Class 12.",\n                    "points": [\n                        "Best for: Students comfortable with detail-oriented, exam-heavy professional study over 3–5 years",\n                        "Outcome: Chartered Accountant, Company Secretary, Cost Accountant — all in high demand"\n                    ],\n                    "links": [\n                        {\n                            "label": "CA / CS / CMA Courses",\n                            "href": "/courses/professional"\n                        },\n                        {\n                            "label": "Finance & Accounts Exams",\n                            "href": "/exams/law/finance-accounts"\n                        }\n                    ]\n                },\n                {\n                    "icon": "BarChart2",\n                    "title": "Banking, Finance & Insurance",\n                    "description": "Careers in banking (PSU and private), financial services, insurance, and investment management are among the most stable and well-paying in the commerce domain. Most entry routes are through degree + competitive exams.",\n                    "points": [\n                        "PSU Banking: IBPS PO/Clerk, SBI PO/Clerk exams",\n                        "Investment / Finance: CFA, CFP for specialised roles",\n                        "Best paired with: B.Com / BBA / MBA (Finance)"\n                    ],\n                    "links": [\n                        {\n                            "label": "Commerce Graduation Courses",\n                            "href": "/courses/commerce-graduation-courses-bcom-allied"\n                        },\n                        {\n                            "label": "Finance & Accounts Exams",\n                            "href": "/exams/law/finance-accounts"\n                        }\n                    ]\n                }\n            ]\n        },\n        "colleges": {\n            "intro": "When choosing a commerce or management college, look for: UGC/AICTE recognition, placement records for your target role (finance vs. marketing vs. consulting), faculty quality, and total cost. For MBA specifically, the college's alumni network and recruiter tie-ups matter significantly for first placements.",\n            "listings": [\n                {\n                    "label": "IIMs — Management Institutes",\n                    "href": "/colleges/iims-management-institutes",\n                    "meta": "National"\n                },\n                {\n                    "label": "Management & Business Colleges",\n                    "href": "/colleges/management-business-colleges",\n                    "meta": "By Field"\n                }\n            ],\n            "checklist": [\n                "UGC / AICTE recognition and university affiliation",\n                "Placement records for your target specialisation (not just overall average)",\n                "Industry connections, internship support, and guest lecture quality",\n                "Total cost: fees + hostel + exam fees + study material",\n                "For CA/CS/CMA: institute matters less — the exam board credential is what counts"\n            ]\n        }\n    }	t	2026-07-26 17:20:17	2026-07-26 17:20:17	/courses/business-management/mba
4	law	{\n        "hero": {\n            "title": "Law Career Guide",\n            "subtitle": "Courses, Entrance Exams, Colleges & Career Scope — A Complete Roadmap",\n            "description": "A career in law offers one of the most intellectually demanding and socially impactful paths available — but navigating it requires clarity. Integrated LLB or 3-year LLB, CLAT or AILET, NLU or state law college, litigation or corporate law — the choices start early and each one shapes your direction significantly. This page simplifies it all.",\n            "description2": "Whether you're a Class 12 student planning to take the 5-year integrated law route, or a graduate considering the 3-year LLB, you'll find clear pathways, exam guidance, career options, and direct links to detailed pages across the portal — so you can move forward with confidence.",\n            "heroStats": [\n                {\n                    "icon": "ClipboardList",\n                    "label": "Main entrance exam",\n                    "value": "CLAT / AILET"\n                },\n                {\n                    "icon": "BadgeCheck",\n                    "label": "Need guidance?",\n                    "value": "Counselor Support"\n                }\n            ],\n            "quickLinks": [\n                {\n                    "desc": "Full career overview for law as a profession.",\n                    "href": "/career/by-profession/law",\n                    "icon": "GraduationCap",\n                    "title": "Law — By Profession"\n                },\n                {\n                    "desc": "BA LLB / BBA LLB / B.Sc LLB after Class 12.",\n                    "href": "/exams/law/law",\n                    "icon": "Scale",\n                    "title": "5-Year Integrated LLB"\n                },\n                {\n                    "desc": "Law degree for graduates from any stream.",\n                    "href": "/exams/law/law",\n                    "icon": "BookOpen",\n                    "title": "3-Year LLB"\n                },\n                {\n                    "desc": "NLUs — India's top law institutes.",\n                    "href": "/colleges/national-law-universities-nlus",\n                    "icon": "Landmark",\n                    "title": "National Law Universities"\n                }\n            ]\n        },\n        "primaryExam": {\n            "heading": "CLAT: The Main Law Entrance Exam",\n            "intro": "CLAT (Common Law Admission Test) is the centralised national entrance exam for admission to undergraduate and postgraduate law programmes at the National Law Universities (NLUs) across India. A strong CLAT score is the most direct route to the top law schools in the country. If your goal is an NLU seat — especially in a government NLU — CLAT preparation is your most important step.",\n            "quickFacts": [\n                {\n                    "label": "Sections",\n                    "value": "English · GK · Legal Reasoning · Logical Reasoning · Quantitative"\n                },\n                {\n                    "label": "Question Type",\n                    "value": "Comprehension-based MCQ"\n                },\n                {\n                    "label": "Used For",\n                    "value": "UG & PG Law Admissions (NLUs)"\n                }\n            ],\n            "purpose": "Admission to the 5-year integrated BA LLB / BBA LLB / B.Sc LLB programmes (UG-CLAT) at NLUs. Also used for LLM admissions (PG-CLAT) at NLUs. The Consortium of NLUs conducts CLAT; 24 NLUs currently participate in the centralised counselling process.",\n            "eligibility": [\n                {\n                    "category": "UG-CLAT (General)",\n                    "details": "Passed Class 12 from any stream. Minimum 45% aggregate marks"\n                },\n                {\n                    "category": "UG-CLAT (SC / ST)",\n                    "details": "Passed Class 12 from any stream. Minimum 40% aggregate marks"\n                },\n                {\n                    "category": "PG-CLAT (LLM)",\n                    "details": "LLB degree (3-year or 5-year integrated). Minimum 55% aggregate (50% for SC/ST)"\n                }\n            ],\n            "applyMode": "Online Application Mode (consortiumofnlus.ac.in)",\n            "officialWebsite": "https://consortiumofnlus.ac.in/",\n            "unlocks": [\n                "24 NLUs — NLSIU Bangalore, NALSAR Hyderabad, NLU Delhi (via AILET), WBNUJS Kolkata, and others",\n                "Top law firm placements — AZB, Cyril Amarchand, Khaitan, S&R, Trilegal, and other Tier-1 firms",\n                "Corporate legal roles — in-house counsel at banks, PSUs, and MNCs",\n                "Civil Services / Judiciary — NLU graduates are well-positioned for judicial services and UPSC",\n                "LLM and international study — NLU degree is recognised for applications to Oxford, Harvard, and other global law schools"\n            ],\n            "otherExams": [\n                {\n                    "name": "AILET",\n                    "description": "All India Law Entrance Test — conducted by NLU Delhi for admission to its own programmes. Separate from CLAT; NLU Delhi does not participate in the CLAT consortium."\n                },\n                {\n                    "name": "LSAT India",\n                    "description": "Conducted by LSAC. Accepted by Jindal Global Law School and several private law colleges. The test format differs from CLAT and is less current-affairs dependent."\n                },\n                {\n                    "name": "State Law Exams",\n                    "description": "Many states conduct their own law entrance exams for state law university admissions. West Bengal has WBJEE Law for state-level law college admissions."\n                }\n            ],\n            "whoShouldFocusIntro": "CLAT rewards students who read widely, think analytically, and can apply reasoning to unfamiliar situations. It is less about memorised facts and more about comprehension and logical application — a different preparation style from science entrance exams.",\n            "whoShouldFocusPoints": [\n                "You enjoy reading — news, arguments, and current affairs naturally",\n                "You are interested in justice, policy, business law, or advocacy",\n                "You can maintain consistent preparation across English, GK, and reasoning for 6–12 months",\n                "You are from any stream — Class 12 (Arts, Commerce, or Science) students are all eligible"\n            ],\n            "prepPlan": [\n                {\n                    "title": "Read every day — this is non-negotiable for CLAT",\n                    "description": "CLAT's comprehension-heavy format means reading speed and understanding directly impact your score. Read a quality newspaper daily (The Hindu or Indian Express), focus on editorials, legal news, and current affairs. This builds both GK and English simultaneously."\n                },\n                {\n                    "title": "Legal Reasoning — understand principles, not just rules",\n                    "description": "Legal Reasoning in CLAT does not require prior legal knowledge. Each question comes with a passage that contains a legal principle — you apply it to a given situation. Practise by reading the principle carefully, identifying the key rule, and applying it logically without bringing in outside knowledge."\n                },\n                {\n                    "title": "GK and current affairs — build a consistent revision system",\n                    "description": "CLAT GK is largely current affairs from the past 12 months, with some static GK (legal, constitutional, and general). Use a monthly current affairs digest and revise it regularly. Cramming GK the week before the exam rarely works — consistent monthly revision does."\n                },\n                {\n                    "title": "Timed mock tests — speed and accuracy together",\n                    "description": "CLAT is a 2-hour, 120-question exam with 0.25 negative marking. Time management is critical — most students attempt fewer questions than they should. Regular full-length mocks train you to read passages quickly, prioritise questions, and maintain accuracy under time pressure."\n                }\n            ]\n        },\n        "pathways": {\n            "title": "Choose Your Law Pathway",\n            "subtitle": "Pick your stage, then follow the most realistic path based on your eligibility and goals.",\n            "after12": {\n                "title": "After Class 12th — 5-Year Integrated LLB",\n                "description": "The most popular and strategically strong route for aspiring lawyers. A 5-year integrated programme combines an undergraduate degree (BA, BBA, or B.Sc) with a law degree (LLB), allowing you to start practising earlier and with a stronger academic foundation.",\n                "points": [\n                    "Best for: Class 12 students from any stream who are committed to a law career",\n                    "Key exam: CLAT (for NLUs), AILET (NLU Delhi), LSAT India (private colleges), state law exams",\n                    "Popular combinations: BA LLB (humanities + law), BBA LLB (business + law), B.Sc LLB (science + law)"\n                ],\n                "links": [\n                    {\n                        "label": "Law Entrance Exams",\n                        "meta": "Exams",\n                        "href": "/exams/law/law"\n                    },\n                    {\n                        "label": "National Law Universities (NLUs)",\n                        "meta": "Colleges",\n                        "href": "/colleges/national-law-universities-nlus"\n                    },\n                    {\n                        "label": "Law Colleges",\n                        "meta": "Colleges",\n                        "href": "/colleges/law-colleges"\n                    }\n                ]\n            },\n            "afterGraduation": {\n                "title": "After Graduation — 3-Year LLB",\n                "description": "Graduates from any discipline — Commerce, Science, Arts, Engineering — can pursue a 3-year LLB. This route is common for professionals who decide to switch to law or want to add legal qualification to an existing career (e.g., CA + LLB for tax law, Engineer + LLB for IP law).",\n                "points": [\n                    "Best for: Graduates who have decided on law as a second career or want a dual qualification",\n                    "Admission: Most state universities conduct their own 3-year LLB entrance or merit-based admission",\n                    "Career combination advantage: Engineering + LLB (patents), CA + LLB (taxation), MBA + LLB (corporate law)"\n                ],\n                "links": [\n                    {\n                        "label": "Law Entrance Exams",\n                        "meta": "Exams",\n                        "href": "/exams/law/law"\n                    },\n                    {\n                        "label": "Law Colleges",\n                        "meta": "Colleges",\n                        "href": "/colleges/law-colleges"\n                    },\n                    {\n                        "label": "After Graduation Guidance",\n                        "meta": "Stage",\n                        "href": "/careers/after-graduation"\n                    }\n                ]\n            },\n            "afterLLB": {\n                "title": "After LLB — Career Options",\n                "description": "After completing an LLB (3-year or 5-year), you have several well-defined directions. The choice depends on whether you prefer courtroom practice, corporate advisory, academics, or public service.",\n                "careerOptions": [\n                    {\n                        "icon": "Gavel",\n                        "title": "Litigation",\n                        "description": "Enroll with the Bar Council, work as a junior advocate under a senior, build a practice over time. Takes dedication but offers long-term independence."\n                    },\n                    {\n                        "icon": "Landmark",\n                        "title": "Corporate / Law Firms",\n                        "description": "Join a law firm or corporate legal team. Deals with contracts, M&A, compliance, and IPR. Most in-demand at NLU and top private college graduates."\n                    },\n                    {\n                        "icon": "ShieldCheck",\n                        "title": "Judiciary",\n                        "description": "Appear for State Judicial Service exams to become a civil judge. Requires strong preparation in procedural and substantive law. Highly respected and stable career."\n                    },\n                    {\n                        "icon": "BookOpen",\n                        "title": "LLM / Academia",\n                        "description": "Pursue LLM for specialisation (Constitutional Law, IP, Corporate Law, International Law). Required for teaching positions and research roles."\n                    }\n                ]\n            }\n        },\n        "courseBranches": {\n            "intro": "Law is not a single career track — it includes litigation, corporate law, tax law, intellectual property, criminal law, constitutional law, and international law. Your programme and specialisation shape which of these you are best positioned for. Choose based on where you want to practise, not just the prestige of the college.",\n            "cards": [\n                {\n                    "icon": "GraduationCap",\n                    "title": "5-Year Integrated LLB (After Class 12)",\n                    "description": "The most sought-after route. Combines an undergraduate degree with LLB in five years. Variants include BA LLB (most common), BBA LLB (for corporate/business law orientation), and B.Sc LLB (for science-law crossovers like IP law).",\n                    "points": [\n                        "Best for: Class 12 students committed to law as a career from the start",\n                        "Main gate: CLAT · AILET · LSAT India · State law exams",\n                        "Outcome: Advocate, corporate lawyer, judicial services, LLM/abroad"\n                    ],\n                    "links": [\n                        {\n                            "label": "Law Entrance Exams",\n                            "href": "/exams/law/law"\n                        },\n                        {\n                            "label": "National Law Universities",\n                            "meta": "NLUs",\n                            "href": "/colleges/national-law-universities-nlus"\n                        }\n                    ]\n                },\n                {\n                    "icon": "BookOpen",\n                    "title": "3-Year LLB (After Graduation)",\n                    "description": "A 3-year professional law degree open to graduates from any stream. Valued for its flexibility — it allows professionals in other fields to acquire legal knowledge and qualifications without starting over.",\n                    "points": [\n                        "Best for: Graduates who want to add law to an existing career or switch streams",\n                        "Powerful combinations: CA + LLB · Engineer + LLB · MBA + LLB",\n                        "Outcome: Advocate, in-house counsel, compliance officer, legal advisor"\n                    ],\n                    "links": [\n                        {\n                            "label": "Law Colleges",\n                            "href": "/colleges/law-colleges"\n                        }\n                    ]\n                },\n                {\n                    "icon": "Scale",\n                    "title": "LLM — Master of Laws (PG)",\n                    "description": "A 1–2 year postgraduate law degree for specialisation in a specific area of law. Required for teaching law and strengthens profiles for research, international opportunities, and senior legal roles.",\n                    "points": [\n                        "Specialisations: Constitutional Law, IP Law, Corporate Law, Tax Law, International Law, Criminal Law",\n                        "Admission: PG-CLAT (NLUs) or individual university entrance",\n                        "Outcome: Law teacher, researcher, senior advocate, policy advisor"\n                    ],\n                    "links": [\n                        {\n                            "label": "Law Entrance Exams (PG-CLAT)",\n                            "meta": "PG",\n                            "href": "/exams/law/law"\n                        }\n                    ]\n                },\n                {\n                    "icon": "Gavel",\n                    "title": "Judicial Services",\n                    "description": "State Judicial Service exams allow LLB graduates to enter the lower judiciary as civil judges. This is one of the most respected career paths in law — competitive, but with high job security and social prestige.",\n                    "points": [\n                        "Eligibility: LLB degree + Bar enrollment in most states",\n                        "Exam format: Written test (objective + subjective) + viva voce / interview",\n                        "West Bengal: West Bengal Judicial Service (WBJS) for Civil Judge (Junior Division)"\n                    ],\n                    "links": [\n                        {\n                            "label": "Law Career — By Profession",\n                            "href": "/career/by-profession/law"\n                        }\n                    ]\n                }\n            ]\n        },\n        "colleges": {\n            "intro": "In law, the college you attend matters significantly — especially for corporate law placements and international opportunities. NLUs are the gold standard. For litigation and judiciary careers, a recognised state law college is equally effective if you are self-driven. Focus on Bar Council recognition, moot court culture, and internship support when shortlisting.",\n            "listings": [\n                {\n                    "label": "National Law Universities (NLUs)",\n                    "href": "/colleges/national-law-universities-nlus",\n                    "meta": "National"\n                },\n                {\n                    "label": "Law Colleges",\n                    "href": "/colleges/law-colleges",\n                    "meta": "By Field"\n                }\n            ],\n            "checklist": [\n                "Bar Council of India recognition for the LLB programme",\n                "Moot court programme, legal aid clinic, and internship opportunities",\n                "Placement records for law firms (relevant if targeting corporate law)",\n                "Faculty quality and visiting practitioner lectures",\n                "Total cost: fees + hostel + bar exam and enrollment fees"\n            ]\n        }\n    }	t	2026-07-26 17:22:18	2026-07-26 17:22:18	/career/by-profession/law
5	media-journalism	{\n        "hero": {\n            "title": "Media & Journalism Career Guide",\n            "subtitle": "Courses, Entrance Exams, Colleges & Career Scope — A Complete Roadmap",\n            "description": "Media and journalism offer some of the most dynamic and impactful career paths available — but the field is broad. Print journalism, broadcast, digital content, public relations, advertising, film, radio, and social media are all distinct tracks with different skills and entry points. Knowing where you fit makes the difference between a focused path and years of confusion.",\n            "description2": "Whether you're a Class 12 student choosing between a BA in Journalism and a Mass Communication degree, or a graduate looking at postgraduate programmes or industry entry, this page brings together clear pathways, entrance exam guidance, course options, and direct links to detailed pages across the portal.",\n            "heroStats": [\n                {\n                    "icon": "ClipboardList",\n                    "label": "Top PG institute entrance",\n                    "value": "IIMC Entrance Exam"\n                },\n                {\n                    "icon": "BadgeCheck",\n                    "label": "Need guidance?",\n                    "value": "Counselor Support"\n                }\n            ],\n            "quickLinks": [\n                {\n                    "desc": "Full career overview for media and journalism.",\n                    "href": "/careers/media-journalism",\n                    "icon": "GraduationCap",\n                    "title": "Media — By Profession"\n                },\n                {\n                    "desc": "Pathways after Class 12 including media courses.",\n                    "href": "/careers/after-class-12-arts",\n                    "icon": "Newspaper",\n                    "title": "After Class 12 • Arts"\n                },\n                {\n                    "desc": "Entrance exams for mass communication programmes.",\n                    "href": "/exams/design/mass-comm",\n                    "icon": "Mic",\n                    "title": "Mass Comm Exams"\n                },\n                {\n                    "desc": "PG, diploma and career options after your degree.",\n                    "href": "/careers/after-graduation",\n                    "icon": "Camera",\n                    "title": "After Graduation"\n                }\n            ]\n        },\n        "primaryExam": {\n            "heading": "IIMC: India's Top Journalism Institute & Entrance",\n            "intro": "The Indian Institute of Mass Communication (IIMC), New Delhi, is India's most prestigious journalism and mass communication institute. Its annual entrance examination is the most competitive in the country for PG journalism programmes. An IIMC qualification is widely recognised across print, broadcast, and digital media organisations. If your goal is journalism at a national level, IIMC preparation should be your primary focus.",\n            "quickFacts": [\n                {\n                    "label": "Test Areas",\n                    "value": "English · General Knowledge · Current Affairs · Reasoning"\n                },\n                {\n                    "label": "Question Type",\n                    "value": "MCQ + Descriptive / Essay (varies by programme)"\n                },\n                {\n                    "label": "Used For",\n                    "value": "PG Diploma in Journalism & Mass Comm"\n                }\n            ],\n            "purpose": "Admission to PG Diploma programmes in English Journalism, Hindi Journalism, Odia Journalism, Radio & TV Journalism, Advertising & PR, and Development Communication at IIMC campuses across India (New Delhi, Dhenkanal, Aizawl, Amravati, Jammu, Kottayam).",\n            "eligibility": [\n                {\n                    "category": "General Category",\n                    "details": "Bachelor's degree in any discipline. Minimum 50% aggregate marks"\n                },\n                {\n                    "category": "SC / ST / PWD",\n                    "details": "Bachelor's degree in any discipline. Minimum 45% aggregate marks"\n                },\n                {\n                    "category": "Final Year Students",\n                    "details": "Students in the final year of graduation can apply provisionally"\n                }\n            ],\n            "applyMode": "Online Application Mode (iimc.gov.in)",\n            "officialWebsite": "https://iimc.gov.in/",\n            "unlocks": [\n                "Print journalism — newspapers, magazines, and digital news outlets (The Hindu, TOI, NDTV, Wire, etc.)",\n                "Broadcast journalism — TV news reporting, anchoring, production roles at national channels",\n                "Advertising & PR — account management, copywriting, media planning at agencies and corporates",\n                "Development communication — NGOs, UN bodies, government communication, and social impact roles",\n                "Digital media — content strategy, social media, video journalism, and online newsrooms"\n            ],\n            "otherExams": [\n                {\n                    "name": "ACJ — Asian College of Journalism",\n                    "description": "Chennai-based, highly respected for its PG Diploma in Journalism. Has a separate entrance test and interview process. Known for strong print and investigative journalism training."\n                },\n                {\n                    "name": "Symbiosis SET (SCMC)",\n                    "description": "Symbiosis Institute of Media & Communication uses the Symbiosis Entrance Test (SET). Offers programmes in communication management, media studies, and advertising."\n                },\n                {\n                    "name": "University Entrance Tests",\n                    "description": "DU (Delhi University), JMI (Jamia Millia), Calcutta University, and other central and state universities conduct their own entrance tests for BA/MA Journalism and Mass Communication admissions."\n                },\n                {\n                    "name": "FTII / SRFTI — Film & Television",\n                    "description": "The Film and Television Institute of India (FTII, Pune) and Satyajit Ray Film and Television Institute (SRFTI, Kolkata) have separate entrance exams for film direction, editing, cinematography, and production."\n                }\n            ],\n            "whoShouldFocusIntro": "Unlike engineering or medicine, media careers don't run on a single standardised exam or credential. They reward curiosity, communication, and consistent output. The best way to prepare is to both study and practise — write, publish, record, and build a body of work alongside formal education.",\n            "whoShouldFocusPoints": [\n                "You enjoy writing, reporting, storytelling, or visual communication",\n                "You follow current affairs naturally and have opinions on public issues",\n                "You are comfortable with deadlines, ambiguity, and fast-changing environments",\n                "You can work with people — sources, editors, audiences — not just independently"\n            ],\n            "prepPlan": [\n                {\n                    "title": "Read quality journalism every day — this is the preparation",\n                    "description": "The best preparation for journalism entrance exams is reading journalism — newspapers, long-form articles, and investigative reports. It builds vocabulary, comprehension speed, GK, and awareness of how stories are structured simultaneously. Read at least one broadsheet newspaper daily for 6 months before the exam."\n                },\n                {\n                    "title": "Build a current affairs bank — month by month",\n                    "description": "IIMC and similar exams test current affairs heavily — political, economic, cultural, and international news from the past 6–12 months. Maintain a monthly summary of major events, important names, and significant developments. Review it every 2–3 weeks to retain it actively."\n                },\n                {\n                    "title": "Practise writing — essays, opinion pieces, and news summaries",\n                    "description": "Many journalism entrance exams include descriptive or essay sections. Write on current topics regularly — practise structuring an argument, making a clear point, and writing concisely. Share your writing for feedback. A blog or college publication is ideal practice ground."\n                },\n                {\n                    "title": "Apply to multiple programmes — increase your options",\n                    "description": "Unlike CAT or JEE, journalism entrance exams have separate schedules and do not conflict. Apply to IIMC, ACJ, Symbiosis, and relevant university programmes simultaneously. The interview and writing test components mean your personality and genuine interest matter as much as your academic score."\n                }\n            ]\n        },\n        "pathways": {\n            "title": "Choose Your Media & Journalism Pathway",\n            "subtitle": "Pick your stage, then follow the path that matches your interests and background.",\n            "after12": {\n                "title": "After Class 12th",\n                "description": "Class 12 students — especially those from Arts/Humanities — can directly enter undergraduate journalism and mass communication programmes. A BA in Journalism or Mass Communication from a good university is a solid foundation and keeps all specialisations open for the future.",\n                "points": [\n                    "Best for: Students who know media is their field and want to start formal training early",\n                    "Good options: BA Journalism, BA Mass Communication, BMM (Bachelor of Mass Media), B.Sc Electronic Media",\n                    "Important: Build a portfolio alongside your degree — internships, college publications, and social media presence matter at job entry"\n                ],\n                "links": [\n                    {\n                        "label": "After Class 12 • Arts",\n                        "meta": "Stage",\n                        "href": "/career/after-12/arts"\n                    },\n                    {\n                        "label": "Mass Comm Exams",\n                        "meta": "Exams",\n                        "href": "/exams/design/mass-comm"\n                    }\n                ]\n            },\n            "afterGraduation": {\n                "title": "After Graduation",\n                "description": "Graduates from any stream — Arts, Commerce, Science, or Engineering — can pursue postgraduate programmes in journalism or mass communication. The PG route (via IIMC, ACJ, or university MA programmes) is the most structured entry point into competitive national media organisations.",\n                "points": [\n                    "Best for: Graduates who discovered their interest in media during or after their undergraduate years",\n                    "Strong options: IIMC PG Diploma, ACJ PG Diploma, MA Journalism (DU, JMI, Calcutta University), Symbiosis SCMC",\n                    "Career switchers: Science or engineering background can be a strong advantage in science journalism, data journalism, or tech reporting"\n                ],\n                "links": [\n                    {\n                        "label": "Mass Comm Exams",\n                        "meta": "Exams",\n                        "href": "/exams/design/mass-comm"\n                    },\n                    {\n                        "label": "After Graduation Guidance",\n                        "meta": "Stage",\n                        "href": "/careers/after-graduation"\n                    }\n                ]\n            }\n        },\n        "courseBranches": {\n            "intro": "Media careers span traditional and digital formats. Print journalism, broadcast, PR, advertising, digital content, and film are all distinct tracks — each with different skills, daily work, and career trajectories. Many professionals eventually specialise in one area, but starting with a broad mass communication foundation gives you the flexibility to explore before committing.",\n            "cards": [\n                {\n                    "icon": "Newspaper",\n                    "title": "Journalism — Print, Broadcast & Digital",\n                    "description": "Reporting, writing, editing, and publishing news across print, TV, radio, and digital platforms. The core journalism track — competitive but with strong demand in digital newsrooms.",\n                    "points": [\n                        "Best for: Students driven by public interest, current affairs, and storytelling",\n                        "Top institutions: IIMC, ACJ, DU, JMI, Calcutta University",\n                        "Outcome: Reporter, editor, news anchor, digital journalist, documentary filmmaker"\n                    ],\n                    "links": [\n                        {\n                            "label": "Mass Comm & Journalism Exams",\n                            "href": "/exams/design/mass-comm"\n                        }\n                    ]\n                },\n                {\n                    "icon": "Radio",\n                    "title": "Mass Communication (BA / MA)",\n                    "description": "A broader academic programme covering media theory, communication research, media law, advertising, PR, and journalism together. Gives a comprehensive foundation before specialising.",\n                    "points": [\n                        "Best for: Students who want flexibility to explore multiple media tracks before deciding",\n                        "Available at: Most central and state universities as BA / MA / BMM / MMC",\n                        "Outcome: Media professional, researcher, educator, content strategist"\n                    ],\n                    "links": [\n                        {\n                            "label": "Mass Comm Exams",\n                            "href": "/exams/design/mass-comm"\n                        }\n                    ]\n                },\n                {\n                    "icon": "Globe",\n                    "title": "Digital Media & Content Creation",\n                    "description": "The fastest-growing area in media. Covers video production, social media management, podcasting, content strategy, SEO journalism, and online newsrooms. Many roles are accessible through self-learning and a strong portfolio.",\n                    "points": [\n                        "Best for: Students comfortable with technology, platforms, and visual storytelling",\n                        "Entry: Portfolio + relevant UG degree often sufficient; PG programmes available too",\n                        "Outcome: Content creator, digital editor, social media manager, video journalist, podcast producer"\n                    ],\n                    "links": [\n                        {\n                            "label": "Media & Journalism — Career Guide",\n                            "href": "/career/by-profession/media"\n                        }\n                    ]\n                },\n                {\n                    "icon": "Megaphone",\n                    "title": "Public Relations, Advertising & Corporate Comm",\n                    "description": "PR and advertising are distinct from journalism but share the same foundation of communication and storytelling. These tracks offer more structured corporate career paths with strong salary growth.",\n                    "points": [\n                        "Best for: Students interested in brands, campaigns, corporate communication, and events",\n                        "Top programmes: IIMC (Advertising & PR), Symbiosis SCMC, Mudra Institute (MICA)",\n                        "Outcome: PR executive, account manager, brand strategist, media planner, corporate communications officer"\n                    ],\n                    "links": [\n                        {\n                            "label": "Mass Comm Exams",\n                            "href": "/exams/design/mass-comm"\n                        }\n                    ]\n                }\n            ]\n        },\n        "colleges": {\n            "intro": "In media and journalism, the institution you graduate from matters — especially for your first job in competitive national newsrooms and agencies. IIMC and ACJ are the gold standards for PG journalism. For UG, Delhi University, Jamia Millia, and Calcutta University are consistently strong. Private institutes like Symbiosis, Christ University, and MICA also have excellent placement records in advertising and corporate communication.",\n            "listings": [\n                {\n                    "label": "IIMC — Indian Institute of Mass Communication",\n                    "href": "/colleges/iimc",\n                    "meta": "National"\n                },\n                {\n                    "label": "Journalism & Media Colleges",\n                    "href": "/colleges/media-journalism-colleges",\n                    "meta": "By Field"\n                }\n            ],\n            "checklist": [\n                "Industry reputation and alumni network in your target sector (print, broadcast, digital, or PR/Advertising)",\n                "Faculty with professional media experience, not just academic qualifications",\n                "Internship programme quality — internships often lead to first jobs in media",\n                "Portfolio-building opportunities — college publications, radio, TV lab, student-run PR projects",\n                "Placement records for your specific course (journalism vs. PR vs. advertising placements differ significantly)"\n            ]\n        }\n    }	t	2026-07-26 17:23:21	2026-07-26 17:23:21	/career/by-profession/media
6	civil-services	{\n        "hero": {\n            "title": "Civil Services Career Guide",\n            "subtitle": "UPSC, WBCS, Exam Stages, Services & Preparation — A Complete Roadmap",\n            "description": "A career in civil services is one of the most ambitious and respected paths in India — but it demands years of disciplined preparation. UPSC CSE, WBCS, exam stages, optional subjects, syllabus depth, and the reality of multiple attempts can make it hard to know where to begin. This page simplifies everything into one clear place.",\n            "description2": "Whether you are a student in graduation starting to think about civil services, or someone who has already begun preparation and wants to understand the full picture — you'll find clear pathways, exam breakdowns, service options, and honest preparation guidance here.",\n            "heroStats": [\n                {\n                    "icon": "ClipboardList",\n                    "label": "Primary entrance exams",\n                    "value": "UPSC CSE · WBCS"\n                },\n                {\n                    "icon": "BadgeCheck",\n                    "label": "Need guidance?",\n                    "value": "Counselor Support"\n                }\n            ],\n            "quickLinks": [\n                {\n                    "desc": "Full career overview for civil services as a profession.",\n                    "href": "/career/by-profession/civil-services",\n                    "icon": "Landmark",\n                    "title": "Civil Services — By Profession"\n                },\n                {\n                    "desc": "India's most prestigious exam — IAS, IPS, IFS and more.",\n                    "href": "https://upsc.gov.in/",\n                    "icon": "Target",\n                    "title": "UPSC CSE"\n                },\n                {\n                    "desc": "West Bengal Civil Service exam for state-level posts.",\n                    "href": "https://wbpsc.gov.in/",\n                    "icon": "MapPin",\n                    "title": "WBCS"\n                },\n                {\n                    "desc": "Career options and pathways after your degree.",\n                    "href": "/careers/after-graduation",\n                    "icon": "GraduationCap",\n                    "title": "After Graduation"\n                }\n            ]\n        },\n        "primaryExam": {\n            "heading": "UPSC CSE: The Main Civil Services Exam",\n            "intro": "The UPSC Civil Services Examination (CSE) is India's most prestigious competitive exam, conducted by the Union Public Service Commission. It selects officers for the Indian Administrative Service (IAS), Indian Police Service (IPS), Indian Foreign Service (IFS), and over 20 other Group A and B Central Services. A single exam with three progressive stages, UPSC CSE demands sustained preparation across a wide syllabus over 1–3 years for most successful candidates.",\n            "quickFacts": [\n                {\n                    "label": "Stage 1 — Prelims",\n                    "value": "GS Paper I + CSAT (Qualifying) · MCQ · Screening round"\n                },\n                {\n                    "label": "Stage 2 — Mains",\n                    "value": "9 Papers (GS I–IV + Essay + Optional × 2) · Descriptive"\n                },\n                {\n                    "label": "Stage 3 — Interview",\n                    "value": "Personality Test (275 marks) · Reasoning & character"\n                }\n            ],\n            "purpose": "Selection for IAS, IPS, IFS, IRS, and over 20 Group A and B Central Services. Final rank determines service allocation based on preference list.",\n            "eligibility": [\n                {\n                    "category": "Educational",\n                    "details": "Bachelor's degree in any discipline from a recognised university (any stream)"\n                },\n                {\n                    "category": "Age Limit",\n                    "details": "General: 21–32 years · OBC: 21–35 years · SC/ST: 21–37 years"\n                },\n                {\n                    "category": "Attempts",\n                    "details": "General: 6 attempts · OBC: 9 attempts · SC/ST: Unlimited (within age)"\n                }\n            ],\n            "applyMode": "Online Application Mode (upsconline.nic.in)",\n            "officialWebsite": "https://upsc.gov.in/",\n            "services": [\n                {\n                    "name": "IAS",\n                    "description": "Indian Administrative Service — district administration, policy implementation, and senior government positions. Most sought-after service."\n                },\n                {\n                    "name": "IPS",\n                    "description": "Indian Police Service — law enforcement, intelligence, and internal security at state and central levels."\n                },\n                {\n                    "name": "IFS",\n                    "description": "Indian Foreign Service — diplomatic postings, embassies, and international relations. Requires strong language and communication skills."\n                },\n                {\n                    "name": "IRS & others",\n                    "description": "Indian Revenue Service (Customs & IT), IRTS, IRAS, IRPS, IPoS and 20+ other Group A/B central services."\n                }\n            ],\n            "stateExams": {\n                "title": "WBCS: West Bengal Civil Service Exam",\n                "description": "The West Bengal Civil Service (Executive) Examination is conducted by the West Bengal Public Service Commission (WBPSC). It is the state-level equivalent of UPSC CSE and selects officers for the West Bengal Civil Service (Executive) and allied state services.",\n                "examPattern": "Three stages: Preliminary (MCQ) → Main (descriptive, 6 papers) → Personality Test. Syllabus overlaps significantly with UPSC.",\n                "postsAllocated": "WBCS (Exe.), WBPS (Police), Sub-Divisional Officer, Block Development Officer, and several allied Group A/B state services.",\n                "keyDifference": "Bengali language paper is included. State-specific GK (WB history, economy, geography) is tested. Age limit and attempt rules differ.",\n                "officialWebsite": "https://wbpsc.gov.in/"\n            },\n            "whoShouldFocusIntro": "Civil services is not the right choice for everyone — and knowing this early saves years. It suits students who are genuinely motivated by public administration, are comfortable with a multi-year preparation commitment, and can stay focused through uncertainty and repeated cycles.",\n            "whoShouldFocusPoints": [\n                "You are genuinely interested in governance, public policy, and serving at a systemic level — not just the prestige or salary",\n                "You can commit 1–3 years of focused preparation after graduation with limited income in that period",\n                "You enjoy reading across subjects — history, polity, economy, geography, science, and current affairs simultaneously",\n                "You have the emotional resilience to handle an uncertain outcome over multiple attempts"\n            ],\n            "prepPlan": [\n                {\n                    "title": "Understand the syllabus fully before studying anything",\n                    "description": "Download the official UPSC CSE syllabus and read it cover to cover before opening any book. The syllabus defines what is in and what is out. Most beginners waste months studying material that is not tested. Map every topic to the syllabus before you invest time in it."\n                },\n                {\n                    "title": "NCERTs first — build a clean, reliable foundation",\n                    "description": "NCERT textbooks (Class 6–12) for History, Geography, Polity, Economics, and Science are the starting point for most serious aspirants. They are factually reliable, clearly written, and directly relevant to the Prelims syllabus. Read them before moving to standard reference books."\n                },\n                {\n                    "title": "Current affairs — daily reading, monthly consolidation",\n                    "description": "Current affairs is tested heavily in both Prelims and Mains. Read a quality newspaper daily (The Hindu or Indian Express), with a focus on national and international policy, economy, and environment. Every month, consolidate what you read into a structured summary. Don't let it pile up — review it actively."\n                },\n                {\n                    "title": "Answer writing for Mains — start earlier than you think",\n                    "description": "The Mains exam is entirely descriptive — your ability to write structured, analytical answers under time pressure is what separates ranks. Start practising answer writing from the first year of preparation, not just before the exam. Write daily. Get feedback. Quality and structure matter more than volume."\n                }\n            ]\n        },\n        "examStages": {\n            "title": "The Three Stages of UPSC CSE",\n            "subtitle": "Each stage is a filter — understand what each one tests and how to approach it.",\n            "stages": [\n                {\n                    "number": 1,\n                    "title": "Preliminary Examination",\n                    "description": "A screening test. Only marks from GS Paper I count — CSAT (Paper II) is qualifying only (33% needed). Prelims score is not counted in final merit.",\n                    "details": [\n                        "GS Paper I: History, Geography, Polity, Economy, Environment, Science & Tech, Current Affairs",\n                        "CSAT Paper II: Reading comprehension, reasoning, basic numeracy (qualifying)",\n                        "Format: MCQ with ⅓ negative marking",\n                        "Goal: Clear the cut-off to qualify for Mains"\n                    ],\n                    "color": "primary"\n                },\n                {\n                    "number": 2,\n                    "title": "Main Examination",\n                    "description": "The most important stage. 9 papers over several days — all descriptive. 7 papers count for merit; 2 are qualifying. This is where ranks are made.",\n                    "details": [\n                        "Essay Paper: 2 essays on diverse topics (250 marks)",\n                        "GS I–IV: History, Society, Governance, Ethics (250 marks each)",\n                        "Optional Papers: 2 papers from 1 chosen optional subject (250 + 250 marks)",\n                        "Qualifying: Indian Language paper + English paper"\n                    ],\n                    "color": "success"\n                },\n                {\n                    "number": 3,\n                    "title": "Personality Test (Interview)",\n                    "description": "Conducted by a UPSC board. Worth 275 marks — a significant portion of the final merit. Tests intellectual curiosity, balance of judgement, and suitability for civil service.",\n                    "details": [\n                        "Based on your Detailed Application Form (DAF) — be honest and thorough",\n                        "Questions span current affairs, your background, optional subject, and opinion-based scenarios",\n                        "There are no right or wrong answers — clarity of thought and honesty matter",\n                        "Final rank = Mains marks + Interview marks"\n                    ],\n                    "color": "warning"\n                }\n            ]\n        },\n        "optionalSubject": {\n            "title": "Choosing Your Optional Subject",\n            "subtitle": "One of the most important decisions in your UPSC preparation — choose carefully.",\n            "description": "The optional subject contributes 500 marks (2 papers × 250) to your Mains score — a significant chunk of the total 1750 marks. Choosing the right optional can meaningfully improve your rank. There is no single 'best' optional — the right choice depends on your background, genuine interest, and availability of good resources.",\n            "factors": [\n                "Your graduation subject: If you studied Economics, History, or Political Science, leveraging that background saves time",\n                "Overlap with GS: Optionals like History, Geography, PSIR, Sociology have strong overlap with General Studies papers",\n                "Scoring potential: Some optionals (Anthropology, Medical Science, Law) have historically good scoring patterns — but this changes over years",\n                "Resource availability: Choose a subject with good coaching material, previous year papers, and guidance available"\n            ],\n            "commonOptionals": [\n                "History",\n                "Geography",\n                "Political Science & IR",\n                "Sociology",\n                "Public Administration",\n                "Anthropology",\n                "Economics",\n                "Philosophy",\n                "Psychology",\n                "Law"\n            ]\n        },\n        "realityCheck": {\n            "title": "What Civil Services Preparation Actually Demands",\n            "subtitle": "An honest picture before you commit to this path.",\n            "description": "Civil services is one of the most rewarding careers in India — but the preparation path is genuinely demanding and uncertain. Understanding what it actually requires helps you make an informed decision and prepare more effectively if you do choose it.",\n            "journey": [\n                "Most successful candidates prepare for 1.5–3 years before clearing, with many taking 2–3 attempts",\n                "The Prelims cut-off varies each year — clearing it is not guaranteed even with solid preparation",\n                "Mains and Interview preparation require different skills — analytical writing and communication, not just knowledge",\n                "Most aspirants study 6–10 hours daily during the preparation period"\n            ],\n            "successFactors": [\n                "A clear, structured study plan with regular revision — not just coverage of new material",\n                "Answer writing practice from the very first year — not as an afterthought before Mains",\n                "Peer groups and mentors who can give honest feedback on answers and strategy",\n                "Emotional stability and a support system — the preparation period is long and mentally demanding"\n            ],\n            "link": {\n                "label": "Civil Services — Career Overview",\n                "href": "/career/by-profession/civil-services"\n            }\n        }\n    }	t	2026-07-26 17:24:22	2026-07-26 17:24:22	/career/by-profession/civil-services
7	defence	{\n        "hero": {\n            "title": "Defence Forces Career Guide",\n            "subtitle": "Entry Routes, Exams, Services & Preparation — A Complete Roadmap",\n            "description": "A career in the Indian Armed Forces — Army, Navy, or Air Force — is one of the most honourable and structured paths available. But the entry routes are varied and can be confusing: NDA after Class 12, CDS after graduation, AFCAT for Air Force, TES for technical entry, and many more. Each has its own eligibility, exam, and selection process. This page maps it all clearly.",\n            "description2": "Whether you're a Class 11–12 student aiming for NDA, or a graduate targeting a commissioned officer role through CDS or AFCAT — you'll find the right entry route, exam details, preparation guidance, and honest expectations here.",\n            "heroStats": [\n                {\n                    "icon": "ClipboardList",\n                    "label": "Primary entry exams",\n                    "value": "NDA · CDS · AFCAT"\n                },\n                {\n                    "icon": "BadgeCheck",\n                    "label": "Need guidance?",\n                    "value": "Counselor Support"\n                }\n            ],\n            "quickLinks": [\n                {\n                    "desc": "Full career overview for defence as a profession.",\n                    "href": "/career/by-profession/defence",\n                    "icon": "Shield",\n                    "title": "Defence — By Profession"\n                },\n                {\n                    "desc": "Officer entry after Class 12 — Army, Navy, Air Force.",\n                    "href": "/exams/agri/defence",\n                    "icon": "Target",\n                    "title": "NDA Exam"\n                },\n                {\n                    "desc": "Graduate-level commissioned officer entries.",\n                    "href": "/exams/agri/defence",\n                    "icon": "Award",\n                    "title": "CDS / AFCAT"\n                },\n                {\n                    "desc": "NDA, CDS, TES, AFCAT, Soldier entry and more.",\n                    "href": "/exams/agri/defence",\n                    "icon": "GraduationCap",\n                    "title": "All Defence Exams"\n                }\n            ]\n        },\n        "primaryExam": {\n            "heading": "NDA: The Main Entry After Class 12",\n            "intro": "The National Defence Academy (NDA) examination, conducted by UPSC, is the most prestigious entry route into the Indian Armed Forces for students straight out of Class 12. Selected candidates join the NDA at Khadakwasla (Pune) for a 3-year joint training programme, after which they are commissioned as officers into the Army, Navy, or Air Force. If your goal is to become a commissioned officer and you are still in school, NDA is the earliest and most direct route available.",\n            "quickFacts": [\n                {\n                    "label": "Written Test",\n                    "value": "Mathematics + General Ability Test (GAT)"\n                },\n                {\n                    "label": "Selection Stages",\n                    "value": "Written Exam → SSB Interview → Medical"\n                },\n                {\n                    "label": "Conducted By",\n                    "value": "UPSC (twice a year)"\n                }\n            ],\n            "purpose": "Selection for commissioned officer roles in Indian Army, Navy, and Air Force through the National Defence Academy. Cadets receive 3 years of joint training followed by service-specific academy training.",\n            "eligibility": [\n                {\n                    "category": "Age",\n                    "details": "16.5 to 19.5 years at the time of commencement of the course (unmarried male candidates only)"\n                },\n                {\n                    "category": "Education",\n                    "details": "Class 12 passed or appearing. Army: Any stream. Navy / Air Force: PCM compulsory"\n                },\n                {\n                    "category": "Physical Standards",\n                    "details": "Height, weight, and vision standards apply. Medical fitness is tested after clearing written exam and SSB."\n                }\n            ],\n            "applyMode": "Online via UPSC (upsconline.nic.in) — two notifications per year",\n            "officialWebsite": "https://upsc.gov.in/",\n            "ndaAcademyWebsite": "https://www.nda.nic.in/",\n            "unlocks": [\n                "Indian Army — further training at IMA (Indian Military Academy, Dehradun); commissioned as Lieutenant",\n                "Indian Navy — further training at INA (Indian Naval Academy, Ezhimala); commissioned as Sub-Lieutenant",\n                "Indian Air Force — further training at AFA (Air Force Academy, Hyderabad); commissioned as Flying Officer",\n                "B.Sc degree from JNU upon NDA completion (integrated academic programme)",\n                "A structured career with salary, allowances, housing, medical, and a pension-backed service life"\n            ],\n            "otherExams": [\n                {\n                    "name": "TES — Technical Entry Scheme (Army)",\n                    "description": "For Class 12 PCM students with 70%+ marks. Direct entry into the Army as a technical officer. No written exam — shortlisting is based on Class 12 marks + SSB interview. Leads to B.Tech + commission."\n                },\n                {\n                    "name": "10+2 Cadet Entry Scheme (Navy)",\n                    "description": "Entry into the Indian Navy for PCM students after Class 12. Selected candidates undergo B.Tech training at IIEST (formerly BEIT) and are commissioned as officers upon completion."\n                }\n            ],\n            "whoShouldFocusIntro": "NDA is suited for students who have a strong, genuine desire for a life of service, discipline, and adventure — not just a government job with good pay. The training is physically and mentally demanding, and the lifestyle is fundamentally different from civilian careers.",\n            "whoShouldFocusPoints": [\n                "You have a genuine interest in national service, not just the perks of a defence career",\n                "You are physically fit and willing to maintain high fitness standards throughout your career",\n                "You are comfortable with a structured, disciplined lifestyle — postings, transfers, and service obligations",\n                "You have a strong foundation in Mathematics (essential for the written test and technical branches)"\n            ],\n            "prepPlan": [\n                {\n                    "title": "Master Class 11–12 Mathematics — it is the core",\n                    "description": "The Mathematics paper (300 marks) covers Class 11–12 topics: Algebra, Calculus, Trigonometry, Matrices, Probability, and Analytical Geometry. A strong Maths score is the most reliable way to clear the written cut-off. Focus on concept clarity and speed — practice previous year papers regularly."\n                },\n                {\n                    "title": "GAT — build GK, English, and science simultaneously",\n                    "description": "The General Ability Test (GAT, 600 marks) covers English, Physics, Chemistry, Geography, History, Current Affairs, and General Science. Read a newspaper daily for English and GK. Revise NCERT Science and Social Studies for the subject sections. This section rewards consistent, broad reading — not cramming."\n                },\n                {\n                    "title": "Physical fitness — train from the start, not just before SSB",\n                    "description": "The SSB process and NDA training both demand a high level of physical fitness. Start running, swimming, and building general fitness from your Class 11 itself — do not wait until after the written exam. A strong physical base also builds the mental confidence and discipline that SSB assessors look for."\n                },\n                {\n                    "title": "Prepare for the SSB — it is a different kind of test",\n                    "description": "The SSB (Services Selection Board) is a 5-day psychological and personality assessment — not an exam you can cram for. Read about the SSB process early, understand what Officer Like Qualities (OLQs) mean, and work genuinely on your communication, leadership awareness, and self-confidence. Authenticity matters more than prepared answers."\n                }\n            ]\n        },\n        "entryRoutes": {\n            "title": "Entry Routes by Stage",\n            "subtitle": "Choose the right entry route based on where you are in your education.",\n            "after10": {\n                "title": "After Class 10th — Soldier / Airman / Sailor (Other Ranks)",\n                "description": "Class 10 pass candidates can apply for various non-officer (Other Ranks) roles in the Armed Forces. These are essential, respected positions — not lesser careers. They offer a structured service life, good pay, and clear promotion pathways.",\n                "points": [\n                    "Indian Army: Agniveer (Agnipath scheme) in various categories — General Duty, Technical, Clerk, Tradesman",\n                    "Indian Navy: Agniveer (SSR, MR) — Sailor roles in technical and non-technical trades",\n                    "Indian Air Force: Agniveer Vayu — Airman roles across science, arts, and commerce streams (Class 12 required)"\n                ],\n                "links": [\n                    {\n                        "label": "Defence Exams — All Routes",\n                        "meta": "Exams",\n                        "href": "/exams/agri/defence"\n                    }\n                ]\n            },\n            "after12": {\n                "title": "After Class 12th — Officer Entry via NDA / TES",\n                "description": "The most sought-after officer entry routes begin right after Class 12. NDA is the primary and most prestigious route. TES (Army) and 10+2 Cadet Entry (Navy) are additional technical pathways for PCM students.",\n                "points": [\n                    "NDA: Any stream for Army; PCM compulsory for Navy/Air Force — UPSC written exam + SSB + Medical",\n                    "TES (Army): PCM with 70%+ in Class 12 — merit-based shortlisting + SSB + Medical",\n                    "10+2 Cadet Entry (Navy): PCM students — leads to B.Tech + Naval commission"\n                ],\n                "links": [\n                    {\n                        "label": "Defence Exams (NDA / TES)",\n                        "meta": "Exams",\n                        "href": "/exams/agri/defence"\n                    },\n                    {\n                        "label": "Defence — Career Overview",\n                        "meta": "Career",\n                        "href": "/career/by-profession/defence"\n                    }\n                ]\n            },\n            "afterGraduation": {\n                "title": "After Graduation — CDS, AFCAT & Other Entries",\n                "description": "Graduates from any stream can apply for commissioned officer roles through CDS (Combined Defence Services) exam or AFCAT (Air Force Common Admission Test). These are among the most competitive graduate-level officer entries available.",\n                "points": [\n                    "CDS: UPSC exam for IMA (Army), INA (Navy), AFA (Air Force), and OTA (Officers Training Academy) — different educational eligibility for each",\n                    "AFCAT: Air Force Common Admission Test for Flying, Ground Duty (Technical and Non-Technical) branches",\n                    "SSC Technical / Non-Technical (Army): Short Service Commission entries for engineering graduates and non-technical graduates",\n                    "JAG Entry (Army): Judge Advocate General — for law graduates (LLB)"\n                ],\n                "links": [\n                    {\n                        "label": "Defence Exams (CDS / AFCAT)",\n                        "meta": "Exams",\n                        "href": "/exams/agri/defence"\n                    },\n                    {\n                        "label": "After Graduation Guidance",\n                        "meta": "Stage",\n                        "href": "/careers/after-graduation"\n                    }\n                ]\n            }\n        },\n        "services": {\n            "title": "The Three Services",\n            "subtitle": "Understand each service — choose based on genuine interest, not just prestige.",\n            "intro": "The Indian Armed Forces have three distinct services — each with its own culture, branch structure, and career trajectory. While NDA and CDS allow you to indicate a service preference, understanding each one helps you make a more deliberate choice.",\n            "cards": [\n                {\n                    "icon": "Shield",\n                    "title": "Indian Army",\n                    "description": "The largest of the three services. Offers the widest range of officer arms and services — Infantry, Armoured Corps, Artillery, Engineers, Signals, Army Service Corps, Medical, and more.",\n                    "points": [\n                        "Entry routes: NDA, CDS (IMA), TES, SSC",\n                        "Training: IMA, Dehradun",\n                        "Career breadth: Operations, administration, technical, intelligence, logistics"\n                    ]\n                },\n                {\n                    "icon": "Anchor",\n                    "title": "Indian Navy",\n                    "description": "Smaller and more technical than the Army. Officer roles include Executive (ship operations and command), Engineering, Electrical, Education, and Naval Architecture branches.",\n                    "points": [\n                        "Entry routes: NDA (PCM), CDS (INA), 10+2 Cadet Entry",\n                        "Training: INA, Ezhimala (Kerala)",\n                        "Career breadth: Warships, submarines, aviation, maritime operations"\n                    ]\n                },\n                {\n                    "icon": "Wind",\n                    "title": "Indian Air Force",\n                    "description": "The most technically specialised service. Flying Branch (pilots), Ground Duty Technical (engineering), and Ground Duty Non-Technical (administration, logistics, education, accounts) are the main tracks.",\n                    "points": [\n                        "Entry routes: NDA (PCM), CDS (AFA), AFCAT",\n                        "Training: AFA, Hyderabad (Dundigal)",\n                        "Career breadth: Fighter/transport/helicopter flying, aerospace engineering, air traffic control"\n                    ]\n                }\n            ]\n        },\n        "ssbInterview": {\n            "title": "The SSB Interview — What It Actually Is",\n            "subtitle": "Every officer entry route ends here. Understand it before you begin preparation.",\n            "description": "The Services Selection Board (SSB) is a 5-day psychological, physical, and leadership assessment conducted at various centres across India. It is not an exam you can crack with last-minute preparation — it tests who you genuinely are, not what you have memorised. Understanding the SSB process early gives you time to develop the qualities it looks for rather than just practising for it.",\n            "process": [\n                "Day 1 — Screening: Officer Intelligence Rating (OIR) test + Picture Perception and Description Test (PPDT). About 60% of candidates are screened out here.",\n                "Days 2–4 — Psychological & GTO Tests: Thematic Apperception Test, Word Association, Situation Reaction Test, Group Discussions, Group Planning Exercise, Outdoor GTO tasks",\n                "Day 4 — Personal Interview: In-depth one-on-one interview with an Interviewing Officer",\n                "Day 5 — Conference: Final board conference; results announced. Recommended candidates proceed to medical examination."\n            ],\n            "olqs": [\n                "Effective Intelligence",\n                "Reasoning Ability",\n                "Organising Ability",\n                "Power of Expression",\n                "Social Adaptability",\n                "Cooperation",\n                "Sense of Responsibility",\n                "Initiative",\n                "Self Confidence",\n                "Speed of Decision",\n                "Ability to Influence",\n                "Liveliness",\n                "Determination",\n                "Courage",\n                "Stamina"\n            ]\n        },\n        "realityCheck": {\n            "title": "What a Defence Career Actually Demands",\n            "subtitle": "An honest look at service life before you commit to this path.",\n            "description": "A defence career is among the most rewarding — but it requires a genuinely different lifestyle commitment compared to civilian careers. Understanding what it actually involves helps you prepare with the right mindset.",\n            "offers": [\n                "Early responsibility — junior officers lead teams from day one",\n                "Structured pay, allowances, housing, medical, and a strong pension-backed retirement package",\n                "Adventure, physical challenge, and a strong sense of brotherhood and purpose",\n                "Post-retirement opportunities in corporate security, defence PSUs, and government advisory roles"\n            ],\n            "requires": [\n                "Postings across India (and sometimes abroad) — family relocation is a regular part of service life",\n                "Sustained physical fitness throughout your career — not just during selection",\n                "Willingness to serve in remote or operationally active areas when required",\n                "Acceptance that the career path is service-first — personal preferences are secondary to operational requirements"\n            ],\n            "link": {\n                "label": "Defence Forces — Career Overview",\n                "href": "/career/by-profession/defence"\n            }\n        }\n    }	t	2026-07-26 17:25:19	2026-07-26 17:25:19	/career/by-profession/defence
